/* 在正常開啟的原站閱讀頁執行，只調整版面，不下載或解除隱藏內容。 */
(()=>{if(document.querySelector('#quiet-source-controls'))return;const content=document.querySelector('#content')||document.querySelector('article');if(!content){alert('找不到正文，請先正常開啟章節。');return}const style=document.createElement('style');style.textContent='body{background:#f5f2ea!important}#content,article{font-family:"Songti TC",serif!important;font-size:22px!important;line-height:2.1!important;letter-spacing:.04em!important;max-width:680px!important;margin:auto!important;padding:25px!important;background:#f5f2ea!important;color:#303b36!important}#quiet-source-controls{position:fixed;bottom:15px;left:50%;transform:translateX(-50%);z-index:2147483647;background:#303b36;color:#fff;padding:8px;border-radius:25px;display:flex;align-items:center;font:13px sans-serif}#quiet-source-controls button{background:transparent;color:inherit;border:0;padding:10px;cursor:pointer}';document.head.append(style);const box=document.createElement('div');box.id='quiet-source-controls';box.innerHTML='<button data-action="toggle">▷</button><button data-action="slower">−</button><span>18 px/s</span><button data-action="faster">＋</button><button data-action="close">還原</button>';document.body.append(box);let speed=18,run=false,raf,prev=0,y=scrollY;function tick(t){if(run&&!document.hidden){if(prev)y+=Math.min(t-prev,50)*speed/1000;scrollTo(0,y);prev=t;if(innerHeight+scrollY>=document.documentElement.scrollHeight-2)pause()}else prev=0;raf=requestAnimationFrame(tick)}function pause(){run=false;prev=0;box.querySelector('button').textContent='▷'}function manual(e){if(!box.contains(e.target))pause()}for(const e of ['wheel','touchstart','pointerdown'])document.addEventListener(e,manual,{passive:true});document.addEventListener('visibilitychange',pause);box.onclick=e=>{const a=e.target.dataset.action;if(a==='toggle'){run=!run;y=scrollY;prev=0;e.target.textContent=run?'Ⅱ':'▷'}if(a==='slower'||a==='faster'){speed=Math.max(2,Math.min(80,speed+(a==='slower'?-.5:.5)));box.querySelector('span').textContent=speed+' px/s'}if(a==='close'){cancelAnimationFrame(raf);style.remove();box.remove();for(const ev of ['wheel','touchstart','pointerdown'])document.removeEventListener(ev,manual);document.removeEventListener('visibilitychange',pause)}};raf=requestAnimationFrame(tick)})();
